fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // All three vectors must have the same length.
    assert_eq!(condition.len(), x.len(), "condition and x must have the same length");
    assert_eq!(x.len(), y.len(), "x and y must have the same length");

    // Perform element-wise selection.
    condition
        .into_iter()
        .zip(x.into_iter())
        .zip(y.into_iter())
        .map(|((cond, xv), yv)| if cond { xv } else { yv })
        .collect()
}